import React, { useState } from 'react';

const items = ['alpha', 'beta', 'gamma'];

function Badge({ label, ...props }) {
  return <span className="badge" {...props}>{label}</span>;
}

export function List({ title, onSelect }) {
  const [selected, setSelected] = useState(null);
  const handle = (item) => {
    setSelected(item);
    onSelect?.(item);
  };
  return (
    <section aria-label={title}>
      <h2>{title} &amp; more</h2>
      {/* list of items */}
      <ul>
        {items.map((item) => (
          <li key={item} onClick={() => handle(item)}>
            {item === selected ? <Badge label={item} /> : item}
          </li>
        ))}
      </ul>
      <>
        <Layout.Footer disabled text="done" />
      </>
    </section>
  );
}

